package edu.stanford.nlp.sempre.cache;

import java.io.*;
import java.net.*;

import fig.basic.LogInfo;

/**
 * Cache backed by a remote service (see StringCacheServer).
 *
 * @author Percy Liang
 */
public class RemoteStringCache implements StringCache {
  public static final int NUM_TRIES = 5;

  private Socket socket;
  private PrintWriter out;
  private BufferedReader in;

  // Cache things locally.
  private FileStringCache local = new FileStringCache();

  public RemoteStringCache(String path, String host, int port) {
    try {
      LogInfo.begin_track("RemoteStringCache: connecting to %s:%s to access %s", host, port, path);
      this.socket = new Socket(host, port);
      this.out = new PrintWriter(socket.getOutputStream(), true);
      this.in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
      String response = makeRequest("open", path, null);
      LogInfo.logs("Using cache path=%s, host=%s, port=%s", path, host, port);
      if (!response.equals("OK")) {
        throw new RuntimeException(response);
      }
      LogInfo.end_track();
    } catch (UnknownHostException e) {
      LogInfo.end_track();
      throw new RuntimeException(e);
    } catch (IOException e) {
      LogInfo.end_track();
      throw new RuntimeException(e);
    }
  }

  public String makeRequest(String method, String key, String value) {
    try {
      if (value == null)
        out.println(method + "\t" + key);
      else
        out.println(method + "\t" + key + "\t" + value);
      out.flush();
      for (int i = 0; i < NUM_TRIES; i++) {
        try {
          String result = in.readLine();
          if (result.equals(StringCacheServer.nullString)) result = null;
          return result;
        } catch (NullPointerException e) {
          LogInfo.logs("RemoteStringCache.makeRequest(%s, %s, %s) failed", method, key, value);
        }
      }
      throw new NullPointerException();
    } catch (SocketTimeoutException e) {
      throw new RuntimeException(e);
    } catch (IOException e) {
      throw new RuntimeException(e);
    }
  }

  public String get(String key) {
    // First check the local cache.
    String value = local.get(key);
    if (value == null)
      value = makeRequest("get", key, null);
    return value;
  }

  public void put(String key, String value) {
    local.put(key, value);
    makeRequest("put", key, value);
  }

  public int size() { return local.size(); }
}

package edu.stanford.nlp.sempre.cache.test;

import edu.stanford.nlp.sempre.cache.FileStringCache;
import fig.basic.IOUtils;
import fig.basic.MemUsage;

import org.testng.annotations.Test;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.testng.AssertJUnit.assertEquals;

/**
 * @author Roy Frostig
 */
public class StringCacheTest {
  private int numLines(BufferedReader in) throws IOException {
    int n = 0;
    while (in.readLine() != null) n++;
    return n;
  }

  /**
   * Check that we flush at the given frequency
   * @throws IOException
   */
  @SuppressWarnings("deprecation")
  @Test(groups = "fs")
  public void testFlush() throws IOException {
    FileStringCache.opts.appendMode = false;
    FileStringCache.opts.capacity = 1;
    FileStringCache.opts.flushFrequency = 10;
    FileStringCache.opts.verbose = 5;

    final String fs = "StringCacheTest-cache.tmp";
    final Path fsPath = FileSystems.getDefault().getPath(fs);

    Files.deleteIfExists(fsPath);
    FileStringCache cache = new FileStringCache();
    cache.init(fs);

    for (int i = 0; i <= 100; i++) {
      String key = "key:" + i;
      String val = "val:" + i;
      cache.put(key, val);
      assertEquals(cache.getNumTouches(), i + 1);
      if (i > 0 && i % 10 == 0) {
        int lines = numLines(IOUtils.openInHard(fs));
        System.out.println("!!! " + lines + " = " + i);
        assertEquals(lines, i + 1);
      }
    }
    Files.deleteIfExists(fsPath);
  }

  /**
   * Check that we really do evict at the capacity.
   * @throws IOException
   */
  @Test(groups = "fs")
  public void testEvict() throws IOException {
    FileStringCache.opts.appendMode = false;
    FileStringCache.opts.capacity = 10;
    FileStringCache.opts.flushFrequency = 10;
    FileStringCache.opts.verbose = 5;

    final String fs = "StringCacheTest-cache.tmp";
    final Path fsPath = FileSystems.getDefault().getPath(fs);

    Files.deleteIfExists(fsPath);
    FileStringCache cache = new FileStringCache();
    cache.init(fs);

    // Make ~20 MB of string data
    String junk20MB = "junk";
    while (MemUsage.getBytes(junk20MB) <= 20 * 1024 * 1024)
      junk20MB += junk20MB;

    // Make ~1 MB of string data
    String junk1MB = "junk";
    while (MemUsage.getBytes(junk1MB) <= 1024 * 1024)
      junk1MB += junk1MB;

    // Add something small, to be evicted
    cache.put(junk1MB + "1", "test1");
    assertEquals(1, cache.size());
    assert cache.get(junk1MB + "1").equals("test1");

    // Add something small, shouldn't evict anything
    cache.put(junk1MB + "2", "test2");
    assertEquals(2, cache.size());
    assert cache.get(junk1MB + "1").equals("test1");
    assert cache.get(junk1MB + "2").equals("test2");

    // Add something big, to saturate cache and kick out the small entries.
    // Also kicks itself out.
    cache.put(junk20MB + "1", "big1");
    assertEquals(0, cache.size());
    assertEquals(cache.get(junk20MB + "1"), null);

    // Do that again.
    cache.put(junk20MB + "2", "big2");
    assertEquals(0, cache.size());
    assertEquals(cache.get(junk20MB + "2"), null);

    Files.deleteIfExists(fsPath);
  }
}

package edu.stanford.nlp.sempre;

import java.util.List;

import com.google.common.base.Function;
import com.google.common.collect.Lists;

import fig.basic.LispTree;

/**
 * An ActionFormula represent a compositional action used in the interactive
 * package : is used as a prefix to denote an ActionFormula primitive (:
 * actioname args) sequential (:s ActionFormula ActionFormula ...) repeat (:loop
 * Number ActionFormula) conditional (:if Set ActionFormula) block scoping (:blk
 * ActionFormula)
 * 
 * @author sidaw
 */
public class ActionFormula extends Formula {
  public enum Mode {
    primitive(":"), // (: remove *)

    sequential(":s"), // (:s (: add red top) (: remove this))
    repeat(":loop"), // (:loop (count (has color green)) (: add red top))
    conditional(":if"), // (:if (count (has color green)) (: add red top))
    whileloop(":while"), // (:while (count (has color green)) (: add red top))
    forset(":for"), // (:for (and this (color red)) (:s (: add red top) (: add
                    // yellow top) (: remove)))
    foreach(":foreach"), // (:foreach * (add ((reverse color) this) top))

    substitute(":sub"),
    define(":def"),
    defined("::"), // named formula defined using primitives
    label(":label"),

    // primitives for declaring variables
    // let(":let"), // (:let X *),
    // set(":set"), // (:set X *)

    block(":blk"), // start a block of code (like {}) with a new scope
    blockr(":blkr"), // also return a result after finishing the block
    isolate(":isolate"), other(":?");


    private final String value;

    Mode(String value) {
      this.value = value;
    }

    @Override
    public String toString() {
      return this.value;
    }
  };

  public final Mode mode;
  public final List<Formula> args;

  public ActionFormula(Mode mode, List<Formula> args) {
    this.mode = mode;
    this.args = args;
  }

  public static Mode parseMode(String mode) {
    if (mode == null)
      return null;
    for (Mode m : Mode.values()) {
      // LogInfo.logs("mode string %s \t== %s \t!= %s", m.toString(), mode,
      // m.name());
      if (m.toString().equals(mode))
        return m;
    }
    if (mode.startsWith(":"))
      throw new RuntimeException("Unsupported ActionFormula mode");
    return null;
  }

  @Override
  public LispTree toLispTree() {
    LispTree tree = LispTree.proto.newList();
    tree.addChild(this.mode.toString());
    for (Formula arg : args)
      tree.addChild(arg.toLispTree());
    return tree;
  }

  @Override
  public void forEach(Function<Formula, Boolean> func) {
    if (!func.apply(this)) {
      for (Formula arg : args)
        arg.forEach(func);
    }
  }

  @Override
  public Formula map(Function<Formula, Formula> transform) {
    Formula result = transform.apply(this);
    if (result != null)
      return result;
    List<Formula> newArgs = Lists.newArrayList();
    for (Formula arg : args)
      newArgs.add(arg.map(transform));
    return new ActionFormula(this.mode, newArgs);
  }

  @Override
  public List<Formula> mapToList(Function<Formula, List<Formula>> transform, boolean alwaysRecurse) {
    List<Formula> res = transform.apply(this);
    if (res.isEmpty() || alwaysRecurse) {
      for (Formula arg : args)
        res.addAll(arg.mapToList(transform, alwaysRecurse));
    }
    return res;
  }

  @SuppressWarnings({ "equalshashcode" })
  @Override
  public boolean equals(Object thatObj) {
    if (!(thatObj instanceof ActionFormula))
      return false;
    ActionFormula that = (ActionFormula) thatObj;
    if (!this.mode.equals(that.mode))
      return false;
    if (!this.args.equals(that.args))
      return false;
    return true;
  }

  @Override
  public int computeHashCode() {
    int hash = 0x7ed55d16;
    hash = hash * 0xd3a2646c + mode.hashCode();
    hash = hash * 0xd3a2646c + args.hashCode();
    return hash;
  }
}

package edu.stanford.nlp.sempre.interactive;

public class BadInteractionException extends RuntimeException {

  public static BadInteractionException nonSenseDefinition(String head) {
    String message = String.format("Definitions should make sense and useable by yourself and others"
        + "-- using more than 10 words, " + "or more than 15 characters in a word is not allowed."
        + "If your definition is not non-sense," + "please paste this message in our bugs channel (head: %s)", head);
    return new BadInteractionException(message);
  }

  public static BadInteractionException headIsCore(String head) {
    String message = String.format(
        "Redefining the core language is not allowed, " + "please reword your command and try again (head: %s)", head);
    return new BadInteractionException(message);
  }

  public static BadInteractionException headIsEmpty(String head) {
    String message = String.format("Cannot define with an empty head (head: %s)", head);
    return new BadInteractionException(message);
  }

  public BadInteractionException() {
    // TODO Auto-generated constructor stub
  }

  public BadInteractionException(String message) {
    super(message);
    // TODO Auto-generated constructor stub
  }

  public BadInteractionException(Throwable cause) {
    super(cause);
    // TODO Auto-generated constructor stub
  }

  public BadInteractionException(String message, Throwable cause) {
    super(message, cause);
    // TODO Auto-generated constructor stub
  }

  public BadInteractionException(String message, Throwable cause, boolean enableSuppression,
      boolean writableStackTrace) {
    super(message, cause, enableSuppression, writableStackTrace);
    // TODO Auto-generated constructor stub
  }

}

package edu.stanford.nlp.sempre.freebase.utils;

import edu.stanford.nlp.io.IOUtils;
import fig.basic.LogInfo;

import java.io.BufferedReader;
import java.io.IOException;
import java.util.*;
import java.util.regex.Pattern;

public final class LinkedExtractionFileUtils {

  private String extractionFile;
  private static final int ARG1_INDEX = 0;
  private static final int PREDICATE_INDEX = 1;
  private static final int ARG2_INDEX = 2;
  private static final int MID_INDEX = 3;
  public static final Pattern DELIMITER_PATTERN = Pattern.compile("\t");
  public static final String TIME_ARG = "TIME:";


  public LinkedExtractionFileUtils(String extractionFileName) {
    this.extractionFile = extractionFileName;
  }

  public Map<String, Set<String>> getIdToExtractionsMap() throws IOException {

    LogInfo.log("Uploading id-to-extraction-set map");
    Map<String, Set<String>> res = new HashMap<String, Set<String>>();

    BufferedReader reader = IOUtils.getBufferedFileReader(extractionFile);
    String line;
    while ((line = reader.readLine()) != null) {

      String[] tokens = DELIMITER_PATTERN.split(line);

      Set<String> extractionSet = res.get(tokens[MID_INDEX]);
      if (extractionSet == null) {
        extractionSet = new HashSet<String>();
        res.put(tokens[MID_INDEX], extractionSet);
      }
      extractionSet.add(tokens[ARG1_INDEX] + DELIMITER_PATTERN + tokens[PREDICATE_INDEX] + DELIMITER_PATTERN + DELIMITER_PATTERN + tokens[ARG2_INDEX]);
    }
    reader.close();
    LogInfo.log("Done uploading id-to-extraction-set map");
    return res;
  }

  public Set<String> getLinkedIdSet() throws IOException {

    LogInfo.log("Uploading linked MIDs set");
    Set<String> res = new HashSet<String>();

    BufferedReader reader = IOUtils.getBufferedFileReader(extractionFile);
    String line;
    while ((line = reader.readLine()) != null) {

      String[] tokens = DELIMITER_PATTERN.split(line);
      res.add(tokens[MID_INDEX]);
    }
    reader.close();
    LogInfo.log("Done uploading linked IDs set");
    return res;
  }

  public Map<String, Map<String, List<String>>> getIdToArg2ToPredicateListMap() throws IOException {

    LogInfo.begin_track("Uploading id-to-arg-predicate-list-map");
    // BinaryNormalizer normalizer = new BinaryNormalizer();

    Map<String, Map<String, List<String>>> res = new HashMap<String, Map<String, List<String>>>();

    for (String line : IOUtils.readLines(extractionFile)) {

      String[] tokens = DELIMITER_PATTERN.split(line);

      String id = tokens[MID_INDEX];
      String arg2 = tokens[ARG2_INDEX];
      String predicate = tokens[PREDICATE_INDEX];
      // String predicate = normalizer.normalize(tokens[PREDICATE_INDEX]);

      Map<String, List<String>> arg2ToPredicateList = res.get(id);
      if (arg2ToPredicateList == null) {
        arg2ToPredicateList = new HashMap<String, List<String>>();
        arg2ToPredicateList.put(arg2, new LinkedList<String>());
        res.put(id, arg2ToPredicateList);
      }

      List<String> predicateList = arg2ToPredicateList.get(arg2);
      if (predicateList == null) {
        predicateList = new LinkedList<String>();
        arg2ToPredicateList.put(arg2, predicateList);
      }
      predicateList.add(predicate);
    }
    LogInfo.end_track();
    return res;
  }

  public static boolean isTimeArg(String str) {
    return str.startsWith(TIME_ARG);
  }

  public static String extractTime(String str) {
    if (!isTimeArg(str)) {
      throw new RuntimeException("Not a time arg: " + str);
    }
    return str.substring(TIME_ARG.length());
  }
}

package edu.stanford.nlp.sempre.overnight;

import fig.basic.IOUtils;
import fig.basic.LogInfo;
import fig.basic.MapUtils;
import fig.basic.Option;
import edu.stanford.nlp.sempre.*;

import java.util.HashMap;
import java.util.Map;

/**
 * PPDBModel extracts and scores paraphrasing featues from derivations.
 * This model is intended to be used with FloatingParser
 *
 * @author Yushi Wang
 */

public final class PPDBModel {
  public static class Options {
    @Option(gloss = "Path to file with alignment table")
    public String ppdbModelPath = "regex/regex-ppdb.txt";

    @Option(gloss = "Using ppdb format")
    public boolean ppdb = true;
  }

  public static Options opts = new Options();

  public static PPDBModel model;

  Map<String, Map<String, Double>> table;

  // We should only have one paraphrase model
  public static PPDBModel getSingleton() {
    if (model == null) {
      model = new PPDBModel();
    }
    return model;
  }

  private PPDBModel() {
    table = loadPPDBModel(opts.ppdbModelPath);
  }

  /**
   * Loading ppdb model from file
   */
  private Map<String, Map<String, Double>> loadPPDBModel(String path) {
    LogInfo.begin_track("Loading ppdb model");
    Map<String, Map<String, Double>> res = new HashMap<>();
    for (String line: IOUtils.readLinesHard(path)) {
      if (opts.ppdb) {
        String[] tokens = line.split("\\|\\|\\|");
        String first = tokens[1].trim();
        String second = tokens[2].trim();
        String stemmedFirst = LanguageInfo.LanguageUtils.stem(first);
        String stemmedSecond = LanguageInfo.LanguageUtils.stem(second);

        putParaphraseEntry(res, first, second);
        if ((!stemmedFirst.equals(first) || !stemmedSecond.equals(second)) &&
                !stemmedFirst.equals(stemmedSecond))
          putParaphraseEntry(res, stemmedFirst, stemmedSecond);
      } else {
        String[] tokens = line.split("\t");
        MapUtils.putIfAbsent(res, tokens[0], new HashMap<>());
        for (String token : tokens)
          LogInfo.logs("%s", token);
        res.get(tokens[0]).put(tokens[1], 1.0);
      }
    }
    LogInfo.logs("ParaphraseUtils.loadPhraseTable: number of entries=%s", res.size());
    LogInfo.end_track();
    return res;
  }

  private void putParaphraseEntry(Map<String, Map<String, Double>> res, String first, String second) {
    MapUtils.putIfAbsent(res, first, new HashMap<>());
    res.get(first).put(second, 1.0);
  }

  public boolean containsKey(String key) {
    return table.containsKey(key);
  }

  public Double get(String key, String token) {
    if (!table.containsKey(key) || !table.get(key).containsKey(token)) return 0.0;
    return table.get(key).get(token);
  }
}

package edu.stanford.nlp.sempre.freebase;

import edu.stanford.nlp.sempre.*;
import edu.stanford.nlp.sempre.cache.StringCache;
import edu.stanford.nlp.sempre.cache.StringCacheUtils;
import fig.basic.*;
import java.io.*;
import java.net.SocketTimeoutException;
import java.net.URL;
import java.net.URLConnection;
import java.net.URLEncoder;
import java.util.*;

/**
 * Takes a string (e.g., "obama") and asks the Freebase Search API.
 * Caches if necessary.
 * Outputs a set of entities.
 *
 * @author Percy Liang
 */
public class FreebaseSearch {
  public static class Entry {
    public Entry(String mid, String id, String name, double score) {
      this.mid = mid;
      this.id = id;
      this.name = name;
      this.score = score;
    }

    public final String mid;
    public final String id;
    public final String name;
    public final double score;

    public LispTree toLispTree() {
      LispTree tree = LispTree.proto.newList();
      tree.addChild(mid);
      tree.addChild(id == null ? "" : id);
      tree.addChild(name);
      tree.addChild(score + "");
      return tree;
    }

    public String toString() { return toLispTree().toString(); }
  }

  public static class Options {
    @Option(gloss = "Milliseconds to wait until opening connection times out")
    public int connectTimeoutMs = 1 * 60 * 1000;

    @Option(gloss = "Milliseconds to wait until reading connection times out")
    public int readTimeoutMs = 1 * 60 * 1000;

    @Option(gloss = "API key (needed to get more access)")
    public String apiKey;

    @Option(gloss = "Save results of Freebase API search")
    public String cachePath;
  }
  public static Options opts = new Options();

  private final StringCache cache;

  public class ServerResponse {
    public ServerResponse() { this.entries = new ArrayList<>(); this.error = null; }
    public ServerResponse(ErrorValue error) { this.entries = null; this.error = error; }
    public final List<Entry> entries;
    public final ErrorValue error;
    boolean cached;
    long timeMs;
  }

  public FreebaseSearch() {
    if (opts.cachePath != null)
      this.cache = StringCacheUtils.create(opts.cachePath);
    else
      this.cache = null;
  }

  @SuppressWarnings("unchecked")
  public ServerResponse lookup(String query) {
    StopWatch watch = new StopWatch();
    watch.start();
    String output = null;
    ServerResponse response = new ServerResponse();

    // First, try the cache.
    if (cache != null) {
      output = cache.get(query);
      if (output != null) response.cached = true;
    }

    // If got nothing, then need to hit the server.
    if (output == null) {
      try {
        // Setup the connection
        String url = String.format("https://www.googleapis.com/freebase/v1/search?query=%s", URLEncoder.encode(query, "UTF-8"));
        if (opts.apiKey != null) url += "&key=" + opts.apiKey;
        URLConnection conn = new URL(url).openConnection();
        conn.setConnectTimeout(opts.connectTimeoutMs);
        conn.setReadTimeout(opts.readTimeoutMs);
        InputStream in = conn.getInputStream();

        // Read the response
        StringBuilder buf = new StringBuilder();
        BufferedReader reader = new BufferedReader(new InputStreamReader(in));
        String line;
        while ((line = reader.readLine()) != null)
          buf.append(line);
        reader.close();

        // Put the result in the cache
        output = buf.toString();
        if (cache != null)
          cache.put(query, output);

      } catch (SocketTimeoutException e) {
        return new ServerResponse(ErrorValue.timeout);
      } catch (IOException e) {
        LogInfo.errors("Server exception: %s", e);
        if (e.toString().contains("HTTP response code: 408"))
          return new ServerResponse(ErrorValue.server408);
        if (e.toString().contains("HTTP response code: 500"))
          return new ServerResponse(ErrorValue.server500);
        throw new RuntimeException(e);  // Haven't seen this happen yet...
      }
    }

    // Parse the result
    Map<String, Object> results = Json.readMapHard(output);
    for (Object resultObj : (List) results.get("result")) {
      Map<String, Object> result = (Map<String, Object>) resultObj;
      String mid = (String) result.get("mid");
      String id = (String) result.get("id");
      mid = toRDF(mid);
      id = toRDF(id);
      String name = (String) result.get("name");
      double score = (double) result.get("score");
      response.entries.add(new Entry(mid, id, name, score));
    }

    watch.stop();
    response.timeMs = watch.getCurrTimeLong();
    LogInfo.logs("FreebaseSearch %s => %s results (cached=%s)", query, response.entries.size(), response.cached);
    return response;
  }

  // /en/barack_obama => fb:en.barack_obama
  private String toRDF(String s) {
    if (s == null) return s;
    return "fb:" + s.substring(1).replaceAll("/", ".");
  }

  public static void main(String[] args) {
    opts.cachePath = "FreebaseSearch.cache";
    String query = StrUtils.join(args, " ");
    query = "obama";
    FreebaseSearch search = new FreebaseSearch();
    LogInfo.logs("%s", search.lookup(query).entries);
  }
}

package edu.stanford.nlp.sempre.freebase.index;

import fig.basic.LogInfo;
import fig.basic.StopWatch;
import org.apache.lucene.analysis.core.KeywordAnalyzer;
import org.apache.lucene.analysis.standard.StandardAnalyzer;
import org.apache.lucene.document.Document;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.queryparser.classic.ParseException;
import org.apache.lucene.queryparser.classic.QueryParser;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.SimpleFSDirectory;
import org.apache.lucene.util.Version;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.List;
import java.util.regex.Pattern;

public class FbEntitySearcher {

  private final QueryParser queryParser;
  private final IndexSearcher indexSearcher;
  private int numOfDocs = 50;
  private String searchStrategy;

  public FbEntitySearcher(String indexDir, int numOfDocs, String searchingStrategy) throws IOException {

    LogInfo.begin_track("Constructing Searcher");
    if (!searchingStrategy.equals("exact") && !searchingStrategy.equals("inexact"))
      throw new RuntimeException("Bad searching strategy: " + searchingStrategy);
    this.searchStrategy = searchingStrategy;

    queryParser = new QueryParser(
        Version.LUCENE_44,
        FbIndexField.TEXT.fieldName(),
        searchingStrategy.equals("exact") ? new KeywordAnalyzer() : new StandardAnalyzer(Version.LUCENE_44));
    LogInfo.log("Opening index dir: " + indexDir);
    IndexReader indexReader = DirectoryReader.open(SimpleFSDirectory.open(new File(indexDir)));
    indexSearcher = new IndexSearcher(indexReader);
    LogInfo.log("Opened index with " + indexReader.numDocs() + " documents.");

    this.numOfDocs = numOfDocs;
    LogInfo.end_track();
  }

  public synchronized List<Document> searchDocs(String question) throws IOException, ParseException {

    List<Document> res = new LinkedList<Document>();
    if (searchStrategy.equals("exact"))
      question = "\"" + question + "\"";

    ScoreDoc[] hits = getHits(question);

    for (int i = 0; i < hits.length; ++i) {
      int docId = hits[i].doc;
      Document doc = indexSearcher.doc(docId);
      res.add(doc);
    }
    return res;
  }

  private ScoreDoc[] getHits(String question) throws IOException, ParseException {
    Query luceneQuery = queryParser.parse(question);
    ScoreDoc[] hits = indexSearcher.search(luceneQuery, numOfDocs).scoreDocs;
    return hits;
  }

  public static void main(String[] args) throws IOException, ParseException {

    Pattern quit =
        Pattern.compile("quit|exit|q|bye", Pattern.CASE_INSENSITIVE);
    FbEntitySearcher searcher = new FbEntitySearcher(args[0], 10000, args[1]);
    BufferedReader is = new BufferedReader(new InputStreamReader(System.in));
    StopWatch watch = new StopWatch();
    while (true) {
      System.out.print("Search> ");
      String question = is.readLine().trim();
      if (quit.matcher(question).matches()) {
        System.out.println("Quitting.");
        break;
      }
      if (question.equals(""))
        continue;

      watch.reset();
      watch.start();
      List<Document> docs = searcher.searchDocs(question);
      watch.stop();
      for (Document doc : docs) {
        LogInfo.log(
            "Mid: " + doc.get(FbIndexField.MID.fieldName()) + "\t" +
                "id: " + doc.get(FbIndexField.ID.fieldName()) + "\t" +
                "types: " + doc.get(FbIndexField.TYPES.fieldName()) + "\t" +
                "Name: " + doc.get(FbIndexField.TEXT.fieldName()) + "\t" +
                "Popularity: " + doc.get(FbIndexField.POPULARITY.fieldName()));
      }
      LogInfo.logs("Number of docs: %s, Time: %s", docs.size(), watch);
    }
  }
}
